import * as React from 'react';
import * as S from '@primasoftllc/design-system';
import '@primasoftllc/design-system/styles.css';

var states = Object.keys(S.dsFleetState);
function App() {
    var state = React.useState('moving'), course = React.useState(45);
    return <div className="dsstateicon-example">
    <style>{exampleStyles}</style>
    <div className={"demo-stack"}>
    <div className={'control'}>
    <label htmlFor={'object-state'}>
    {'Состояние'}
    </label>
    <select id={'object-state'} value={state[0]} onChange={function (e) { state[1](e.target.value); }}>
    {states.map(function (key) {
            return <option key={key} value={key}>
    {S.dsFleetState[key].label}
    </option>;
        })}
    </select>
    </div>
    <div className={'row'}>
    <div className={'state'} aria-live={'polite'} aria-atomic={'true'}>
    <S.DsStateIcon state={state[0]} course={course[0]} label={S.dsFleetState[state[0]].label + (state[0] === 'moving' ? ', курс ' + course[0] + '°' : '')}/>
    <span>
    {S.dsFleetState[state[0]].label}
    </span>
    </div>
    <S.DsButton size={'sm'} tone={'secondary'} disabled={state[0] !== 'moving'} onClick={function () { course[1]((course[0] + 45) % 360); }}>
    {'Повернуть на 45°'}
    </S.DsButton>
    </div>
    <p className={'cap'}>
    {'Курс: ' + course[0] + '°. Поворот применяется только в движении; 0° — север.'}
    </p>
    </div>
    </div>;
}

const exampleStyles = ".dsstateicon-example{font:var(--ds-type-body);color:var(--ds-fg)}\n.dsstateicon-example .demo-stack{display:flex;flex-direction:column;gap:16px;min-width:0}\n.dsstateicon-example p{margin:0}\n.dsstateicon-example .row{display:flex;flex-wrap:wrap;gap:16px;align-items:center}\n.dsstateicon-example .state{display:flex;align-items:center;gap:8px;min-height:28px}\n.dsstateicon-example .cap{font:var(--ds-type-caption);color:var(--ds-fg-muted);margin:0}\n.dsstateicon-example .control{display:flex;align-items:center;gap:8px;flex-wrap:wrap}\n.dsstateicon-example select{font:var(--ds-type-ui);color:var(--ds-fg);background:var(--ds-surface);border:1px solid var(--ds-border-field);border-radius:var(--ds-radius-xs);height:var(--ds-control-h-sm);max-width:100%;padding:0 8px}\n.dsstateicon-example select:focus-visible{outline:var(--ds-focus-width) solid var(--ds-focus-color);outline-offset:var(--ds-focus-offset)}";

export { App as Example };

